import{_ as o,o as a,c as l,a0 as c}from"./chunks/framework.DW5bL-_G.js";const u=JSON.parse('{"title":"更新日志","description":"ew-color-picker 各版本的变更记录，含修复、新增与文档修正。","frontmatter":{"title":"更新日志","description":"ew-color-picker 各版本的变更记录，含修复、新增与文档修正。"},"headers":[],"relativePath":"guide/changelog.md","filePath":"guide/changelog.md"}'),i={name:"guide/changelog.md"};function d(r,e,t,n,h,s){return a(),l("div",null,[...e[0]||(e[0]=[c('<h1 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h1><h2 id="_2-0-1" tabindex="-1">2.0.1 <a class="header-anchor" href="#_2-0-1" aria-label="Permalink to &quot;2.0.1&quot;">​</a></h2><blockquote><p>本版本改动已合入主线并同步到文档站，npm 包暂未发布，后续会随更多修复统一发布。</p></blockquote><h3 id="修复" tabindex="-1">修复 <a class="header-anchor" href="#修复" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>修复插件开关失效：<code>ewColorPickerPanel: false</code>、<code>ewColorPickerColorMode: false</code>（或对象配置）被默认配置覆盖，实际不生效</li><li>面板容器补充 <code>box-sizing: content-box</code>，不再依赖宿主全局 <code>box-sizing</code> 重置</li><li>移除按视口宽度（<code>max-width: 768px</code>）写死面板、输入框、预设区尺寸的媒体查询，内部尺寸统一由 <code>--panel-width</code> / <code>--panel-height</code> 控制</li><li>预定义色板改为 flex 自动换行，移除硬编码的「每行 10 个」换行规则，修复色块数量与容器宽度不匹配时的错误换行</li></ul><h3 id="新增" tabindex="-1">新增 <a class="header-anchor" href="#新增" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li><code>appendTo</code> 选项：把面板容器挂载到 <code>document.body</code> 或任意容器，避免被弹窗、抽屉、滚动容器的 <code>overflow</code> 裁剪。启用后面板改为相对视口定位，仍按 <code>panelPlacement</code> 计算并做边界翻转，滚动或窗口尺寸变化时自动重算</li><li><code>prefix</code> 选项：自定义全部 CSS 类名前缀（默认 <code>ew-</code>），方便嵌入其他库时避免样式冲突。SCSS 同步提供 <code>$prefix</code> 构建变量，需与 JS 选项保持一致</li></ul><h3 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to &quot;文档&quot;">​</a></h3><ul><li>修正预定义色板、数字输入框的类名，与源码保持一致</li><li>移除不存在的 <code>ewColorPickerBox</code> 嵌套配置写法，统一为顶层选项</li><li>修正 <code>autoPanelPosition</code> 的生效前提说明</li><li>新增 <code>appendTo</code> 选项说明（中英文）</li><li>新增 <code>prefix</code> 选项说明（中英文），含 SCSS 自定义编译示例</li></ul><h2 id="_2-0-0" tabindex="-1">2.0.0 <a class="header-anchor" href="#_2-0-0" aria-label="Permalink to &quot;2.0.0&quot;">​</a></h2><p>首个正式发布版本：核心 + 插件架构、14 个包（13 个 scoped 包 + 无 scope 兼容入口包 <code>ew-color-picker</code>）、双语文档站与在线演示。</p>',11)])])}const _=o(i,[["render",d]]);export{u as __pageData,_ as default};
